import{_ as a,C as n,o as t,c as i,a2 as r,b as c,w as o,a as l,E as d,a3 as h}from"./chunks/framework.mrTIYZc5.js";const k=JSON.parse('{"title":"What is DSO?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-dso.md","filePath":"guide/what-is-dso.md"}'),g={name:"guide/what-is-dso.md"};function u(p,e,m,f,D,S){const s=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=r('<h1 id="what-is-dso" tabindex="-1">What is DSO? <a class="header-anchor" href="#what-is-dso" aria-label="Permalink to &quot;What is DSO?&quot;">​</a></h1><p><strong>Docker Secret Operator (DSO)</strong> is an event-driven secret lifecycle manager for Docker. It provides a native mechanism to synchronize, inject, and rotate secrets from enterprise vaults (AWS, Azure, HashiCorp Vault) directly into containerized workloads.</p><p>DSO is designed to eliminate the risks associated with static secret management, specifically targeting <strong>Secret Proliferation</strong> (credentials left in images, <code>.env</code> files, or host storage) and <strong>Secret Drift</strong> (stale credentials in running containers).</p><h2 id="the-core-design-the-control-loop" tabindex="-1">The Core Design: The Control Loop <a class="header-anchor" href="#the-core-design-the-control-loop" aria-label="Permalink to &quot;The Core Design: The Control Loop&quot;">​</a></h2><p>DSO does not just &quot;copy&quot; secrets; it manages a continuous reconciliation loop that ensures the state of your running containers matches the current state of your secret store.</p>',5)),(t(),c(h,null,{default:o(()=>[d(s,{id:"mermaid-15",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Watcher%5BWatcher%20Engine%5D%20--%3E%7CSecret%20Change%7C%20Strategy%5BStrategy%20Engine%5D%0A%20%20%20%20Strategy%20--%3E%7CDecision%7C%20Reloader%5BReloader%20Controller%5D%0A%20%20%20%20Reloader%20--%3E%7CInjection%7C%20Docker%5BDocker%20API%20%2F%20Target%20Container%5D%0A%20%20%20%20Docker%20--%3E%7CEvent%7C%20Watcher%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<ol><li><strong>Watch</strong>: The system monitors cloud providers for secret updates and the Docker socket for container lifecycle events.</li><li><strong>Analyze</strong>: When a change is detected, the Strategy Engine determines the safest way to rotate the secret (Restart, SIGHUP, or Mount update).</li><li><strong>Inject</strong>: The Tar Streamer securely pushes the new secret into the container&#39;s RAMfs-backed secret mount.</li><li><strong>Reconcile</strong>: The system verifies the container&#39;s health and ensures the rotation was successful.</li></ol><h2 id="core-pillars" tabindex="-1">Core Pillars <a class="header-anchor" href="#core-pillars" aria-label="Permalink to &quot;Core Pillars&quot;">​</a></h2><ul><li><strong>Event-Driven</strong>: Immediate response to secret rotation in the vault or container restarts.</li><li><strong>Zero-Persistence</strong>: Secrets are stored in-process RAM and injected into <code>tmpfs</code>. They never touch the host&#39;s physical disk.</li><li><strong>Docker-Native</strong>: Built to work with Docker Engine and Docker Compose, leveraging native labels (<code>dso.reloader=true</code>) and the Docker socket.</li><li><strong>Least Privilege</strong>: DSO requires only a secure Unix socket connection to Docker and machine-identity-based access to the vault.</li></ul><h2 id="why-dso" tabindex="-1">Why DSO? <a class="header-anchor" href="#why-dso" aria-label="Permalink to &quot;Why DSO?&quot;">​</a></h2><p>While Kubernetes has mature secret operators, the Docker ecosystem has historically lacked a professional-grade alternative to insecure <code>.env</code> files or manual injection. DSO fills this gap by bringing enterprise-grade secret orchestration to teams running Docker on-premise, on the edge, or in standard cloud instances without the overhead of a full orchestration layer.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/design-principles.html">Design Principles</a></strong>: Understand the philosophy behind the project.</li><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: Deep dive into the Watcher, Reloader, and Streamer.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: How we protect secrets from host-level compromise.</li><li><strong><a href="/docs/guide/getting-started.html">Quickstart</a></strong>: Get running in under 2 minutes.</li></ul>',7))])}const _=a(g,[["render",u]]);export{k as __pageData,_ as default};
